from logging import getLogger

from .exceptions import InvalidStatus


class Reporter(object):

    _MISSING_ATTR_ERROR_MSG_TEMPLATE = 'Status without {} attribute cannot be used while generating report'

    @classmethod
    def generate_report_from_status_history(cls, status_history):
        """
        Creates report from provided status history which can be used during check for unexpected statuses.

        :param status_history: collection of detected and lost unexpected statuses;
                               when empty collection is provided then empty report will be generated
        :type status_history: [UnexpectedStatus]
        :return: report generated based on provided status history
        :rtype: str
        :raises InvalidStatus: when unexpected status from history has invalid data
        """
        logger = getLogger()
        logger.debug("Generating report")
        report = ''

        for status in status_history:
            report += '{} {:<8s} component: {}, name: {}, value: {}\n'.format(cls._get_timestamp_from_status(status),
                                                                              cls._get_visibility_from_status(status),
                                                                              status.component,
                                                                              status.name,
                                                                              status.value)

        report = cls._trim_trailing_newline_if_present(report)
        logger.debug("Report generated")
        return report

    @classmethod
    def _get_timestamp_from_status(cls, status):
        try:
            return status.timestamp
        except AttributeError:
            raise InvalidStatus(cls._MISSING_ATTR_ERROR_MSG_TEMPLATE.format('timestamp'))

    @classmethod
    def _get_visibility_from_status(cls, status):
        try:
            return status.visibility.upper()
        except AttributeError:
            raise InvalidStatus(cls._MISSING_ATTR_ERROR_MSG_TEMPLATE.format('visibility'))

    @staticmethod
    def _trim_trailing_newline_if_present(report):
        return report[:-1] if report else report
